         * Saída do estoque - Valor outros
 *
 * @var float
 */
private $fValorOutros = 0;

/**
 * Retorna o valor outros
 *
 * @access public
 * @return float
 */
public function getValorOutros() {
  return $this->fValorOutros;
}

/**
 * Seta o valor outros
 *
 * @access private
 * @param float $fValorOutros
 */
private function setValorOutros($fValorOutros) {
  $this->fValorOutros = $fValorOutros;
}

